import UIKit
final class SeatView: UIView {
    private(set) var occupied = false
    func updateOccupied(_ value: Bool) {
        guard value != occupied else { return }
        occupied = value
        setNeedsDisplay()
    }
    override func draw(_ rect: CGRect) {
        guard let context = UIGraphicsGetCurrentContext() else { return }
        let color: UIColor = occupied ? .systemRed : .systemGreen
        context.setFillColor(color.cgColor)
        context.fill(bounds)
    }
}
let view = SeatView(frame: CGRect(x: 0, y: 0, width: 40, height: 40))
view.updateOccupied(true)
assert(view.occupied)
assert(view.layer.needsDisplay())

